package com.yuewei.plm.module.partner;

import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.yuewei.plm.module.partner.PartnerValues.*;

/** Shared selectable addresses; editing one never rewrites sample movement snapshots. */
@Service @RequiredArgsConstructor
public class SampleLocationService {
 private static final String KIND="sample_location";
 private final PartnerStore store;
 
 public Map<String,Object> page(Map<String,String> query){
  SampleSiteAccess.read(store,query.get("site"));var args=new ArrayList<Object>();String where=where(query,false,false,args);long total=store.jdbc.queryForObject("select count(*) from plm_partner_record where "+where,Long.class,args.toArray());long page=Math.max(1,number(query.getOrDefault("page","1"))),size=Math.max(1,Math.min(100,number(query.getOrDefault("size","50"))));args.add(size);args.add((page-1)*size);
  var rows=store.jdbc.queryForList("select record_id as id,name,status,site,version,data::text,deleted_flag from plm_partner_record where "+where+" order by site,data->>'locationCode',record_id limit ? offset ?",args.toArray());var content=rows.stream().map(row->present(row,false)).toList();markReferenced(content);return Map.of("content",content,"page",page,"size",size,"totalElements",total,"totalPages",(total+size-1)/size);
 }
 public Map<String,Object> options(Map<String,String> query){
  boolean mx=SampleSiteAccess.mexico(store);SampleSiteAccess.read(store,query.get("site"));var args=new ArrayList<Object>();String where=where(query,true,mx,args);long size=Math.max(1,Math.min(100,number(query.getOrDefault("size","50"))));args.add(size+1);var rows=store.jdbc.queryForList("select record_id as id,name,status,site,version,data::text,deleted_flag from plm_partner_record where "+where+" order by site,data->>'locationCode',record_id limit ?",args.toArray());return Map.of("content",rows.stream().limit(size).map(row->present(row,false)).toList(),"hasMore",rows.size()>size,"size",size);
 }
 private String where(Map<String,String> query,boolean active,boolean mx,List<Object> args){
  var clauses=new ArrayList<String>(List.of("kind='sample_location'"));String status=text(query.get("status"));if(active){clauses.add("deleted_flag=0");clauses.add("status='active'");}else{require(status.isEmpty()||Set.of("active","inactive","deleted","all").contains(status),"位置状态筛选无效");if(!status.equals("all"))clauses.add(status.equals("deleted")?"deleted_flag=1":"deleted_flag=0");if(Set.of("active","inactive").contains(status)){clauses.add("status=?");args.add(status);}}String site=SampleSiteAccess.read(store,query.get("site"));if(site.isEmpty())site="CN";if(!site.isEmpty()){clauses.add("site=?");args.add(site);}String keyword=text(query.get("keyword"));if(!keyword.isEmpty()){clauses.add("(name ilike ? or data->>'locationCode' ilike ?)");args.add("%"+keyword+"%");args.add("%"+keyword+"%");}return String.join(" and ",clauses);
 }
 @Transactional public Map<String,Object> create(Map<String,Object> input){
  SampleSiteAccess.write(store,input.get("site"));String request=required(input.get("requestId"),"提交标识"),hash=digest("create",input);Long previous=store.created(KIND,request);if(previous!=null){require(repeated(previous,request,"create",hash),"提交标识已有不同的位置资料，请核对原结果");return detail(previous);}
  var d=values(input,Map.of());unique(d,0);long id=store.createSampleLocation(text(d.get("name")));store.remember(KIND,request,id);store.event(id,"sample_location_create",Map.of("requestHash",hash,"location",d),request);store.save(id,d);return present(load(id,false));
 }
 @Transactional public Map<String,Object> update(long id,Map<String,Object> input){
  var before=load(id,true);SampleSiteAccess.write(store,before.get("site"));String request=required(input.get("requestId"),"提交标识"),hash=digest("update",input);if(repeated(id,request,"update",hash))return present(before);store.check(before,number(input.get("version")));var d=values(input,before);if(!text(before.get("site")).equals(text(d.get("site"))))require(!Boolean.TRUE.equals(referenceData(id).get("referenced")),"已有历史或库存引用的位置不能改变站点，请另建位置");if("active".equals(d.get("status")))d.put("deleted",false);unique(d,id);store.revision(id,before);store.event(id,"sample_location_update",Map.of("requestHash",hash,"before",before,"after",d),request);store.save(id,d);if("active".equals(d.get("status")))store.jdbc.update("update plm_partner_record set deleted_flag=0 where record_id=?",id);return present(load(id,false));
 }
 @Transactional public Map<String,Object> delete(long id,Map<String,Object> input){
  var d=load(id,true);SampleSiteAccess.write(store,d.get("site"));String request=required(input.get("requestId"),"提交标识"),hash=digest("delete",input);if(repeated(id,request,"delete",hash))return present(d);store.check(d,number(input.get("version")));require(!Boolean.TRUE.equals(d.get("deleted")),"位置已从可选目录移除");var refs=referenceData(id);boolean used=Boolean.TRUE.equals(refs.get("referenced"));store.revision(id,d);store.event(id,"sample_location_delete",Map.of("requestHash",hash,"before",d,"references",refs,"inventoryChanged",false),request);d.put("status","inactive");store.save(id,d);if(!used)store.jdbc.update("update plm_partner_record set deleted_flag=1 where record_id=?",id);var out=present(load(id,false),false);out.put("referenced",used);out.putAll(refs);return out;
 }
 Map<String,Object> activeTarget(long id){var d=load(id,true);SampleSiteAccess.write(store,d.get("site"));require(!Boolean.TRUE.equals(d.get("deleted"))&&"active".equals(d.get("status")),"目标位置不存在或已停用，请重新选择位置");d.put("locationId",id);return d;}
 private Map<String,Object> load(long id,boolean lock){
  var rows=store.jdbc.queryForList("select record_id as id,name,status,site,version,data::text,deleted_flag from plm_partner_record where record_id=? and kind='sample_location'"+(lock?" for update":""),id);require(rows.size()==1,"位置不存在");var row=rows.get(0);var d=decode(store.json,row.get("data"));for(String key:List.of("id","name","status","site","version"))d.put(key,row.get(key));d.put("deleted",number(row.get("deleted_flag"))!=0);d.put("locationId",id);d.put("kind",KIND);return d;
 }
 private Map<String,Object> present(Map<String,Object> raw){return present(raw,true);}
 private Map<String,Object> present(Map<String,Object> raw,boolean references){
  var d=raw.containsKey("data")?decode(store.json,raw.get("data")):raw;var out=new LinkedHashMap<String,Object>();for(String key:List.of("id","name","status","site","version"))out.put(key,raw.get(key));out.put("locationCode",text(d.get("locationCode")));out.put("locationParts",map(d.get("locationParts")));out.put("deleted",raw.containsKey("deleted_flag")?number(raw.get("deleted_flag"))!=0:Boolean.TRUE.equals(raw.get("deleted")));if(references){var refs=referenceData(number(raw.get("id")));out.put("referenceCount",refs.get("referenceCount"));out.put("referenced",refs.get("referenced"));}return out;
 }
 private Map<String,Object> values(Map<String,Object> input,Map<String,Object> before){
  var d=new LinkedHashMap<>(before);for(String key:List.of("site","name","status","locationCode","locationParts"))if(input.containsKey(key))d.put(key,input.get(key));String site=SampleSiteAccess.write(store,d.get("site"));require(!site.isEmpty(),"请选择中国或墨西哥站点");d.put("site",site);String name=text(d.get("name"));d.put("name",name);String status=text(d.getOrDefault("status","active"));require(Set.of("active","inactive").contains(status),"位置状态无效");d.put("status",status);if(input.containsKey("locationCode")&&!input.containsKey("locationParts"))d.remove("locationParts");if(input.containsKey("locationParts")&&!input.containsKey("locationCode"))d.remove("locationCode");SampleLocations.normalize(d,"location");require(!name.isEmpty()||!text(d.get("locationCode")).isEmpty(),"请填写位置名称或完整五段位置编码");if(name.isEmpty())d.put("name",text(d.get("locationCode")));return d;
 }
 private void unique(Map<String,Object> d,long id){
  String code=text(d.get("locationCode")),name=text(d.get("name"));String key=text(d.get("site"))+":"+(code.isEmpty()?"name:"+name.toLowerCase(Locale.ROOT):"code:"+code);store.jdbc.queryForList("select pg_advisory_xact_lock(hashtextextended(?,0))","sample-location:"+key);
  boolean exists=Boolean.TRUE.equals(store.jdbc.queryForObject("select exists(select 1 from plm_partner_record where kind='sample_location' and deleted_flag=0 and record_id<>? and site=? and ((?<>'' and data->>'locationCode'=?) or (?='' and coalesce(data->>'locationCode','')='' and lower(name)=lower(?))))",Boolean.class,id,d.get("site"),code,code,code,name));require(!exists,"该站点已有相同位置，请选择已有位置或编辑原记录");
 }
 public Map<String,Object> detail(long id){var d=load(id,false);SampleSiteAccess.read(store,d.get("site"));var out=present(d,false);out.putAll(referenceData(id));return out;}
 public Map<String,Object> references(long id){var d=load(id,false);SampleSiteAccess.read(store,d.get("site"));return referenceData(id);}
 private static String refersTo(String data,String id){return "(jsonb_path_exists("+data+",'$.**.locationId ? (@ == $id)'::jsonpath,jsonb_build_object('id',"+id+"::bigint)) or jsonb_path_exists("+data+",'$.**.toLocationId ? (@ == $id)'::jsonpath,jsonb_build_object('id',"+id+"::bigint)))";}
 private static final String REFERENCE=refersTo("data","?");
 private void markReferenced(List<Map<String,Object>> rows){
  if(rows.isEmpty())return;String in=String.join(",",Collections.nCopies(rows.size(),"?"));var found=store.jdbc.queryForList("select r.record_id as id,(exists(select 1 from plm_partner_record current_ref where current_ref.kind in ('sample','sample_identity','sample_shipment') and "+refersTo("current_ref.data","r.record_id")+") or exists(select 1 from plm_partner_event e join plm_partner_record owner on owner.record_id=e.record_id and owner.kind in ('sample','sample_identity','sample_shipment') where "+refersTo("e.data","r.record_id")+")) as referenced from plm_partner_record r where r.record_id in ("+in+")",rows.stream().map(r->r.get("id")).toArray());var flags=new HashMap<Long,Boolean>();for(var row:found)flags.put(number(row.get("id")),Boolean.TRUE.equals(row.get("referenced")));for(var row:rows)row.put("referenced",flags.getOrDefault(number(row.get("id")),false));
 }
 private Map<String,Object> referenceData(long id){
  boolean mexico=SampleSiteAccess.mexico(store);String scope=mexico?"true":store.access.visibleSqlClause("partner","r.record_id");var referenced=store.jdbc.queryForList("select distinct r.record_id,r.kind,r.code,r.name,r.sample_identity_id,i.code as identity_code,i.name as identity_name,p.short_code as identity_short_code,("+scope+") as visible from plm_partner_record r left join plm_partner_record i on i.record_id=r.sample_identity_id and i.kind='sample_identity' left join plm_supplier_profile p on p.supplier_code=coalesce(nullif(i.supplier_code,''),i.data->>'supplierCode') where r.kind in ('sample','sample_identity','sample_shipment') and ("+refersTo("r.data","?")+" or r.record_id in (select record_id from plm_partner_event where "+REFERENCE+"))",id,id,id,id);long onhand=0;var batches=new HashSet<Long>();var visibleIds=new ArrayList<Long>();var details=new ArrayList<Map<String,Object>>();var sampleRefs=new LinkedHashMap<String,Map<String,Object>>();
  for(var row:referenced){if(!Boolean.TRUE.equals(row.get("visible")))continue;long batch=number(row.get("record_id"));visibleIds.add(batch);if(!"sample".equals(row.get("kind"))){if(!mexico&&"sample_shipment".equals(row.get("kind")))details.add(Map.of("type","shipment","code",text(row.get("code")),"name",text(row.get("name")),"locationId",id));continue;}
   batches.add(batch);var history=store.events(batch);long local=0;String site="";for(var position:maps(SampleLedger.replay(history).view().get("positions")))if(number(position.get("locationId"))==id){local=add(local,number(position.get("onhand")));site=SampleLocations.site(position);}onhand=add(onhand,local);long identity=number(row.get("sample_identity_id"));String sampleCode=SampleCodes.display(row.get("identity_code"),row.get("identity_short_code")),name=text(row.get("identity_name"));if(name.isEmpty())name=text(row.get("name"));String key=identity>0?"identity:"+identity:"batch:"+batch;var sample=sampleRefs.get(key);if(sample==null){sample=new LinkedHashMap<String,Object>();sample.put("type","sample");sample.put("sampleIdentityId",identity);sample.put("sampleCode",sampleCode);sample.put("name",name);sample.put("locationId",id);sample.put("site",site);sample.put("onhand",0L);sampleRefs.put(key,sample);}sample.put("onhand",add(number(sample.get("onhand")),local));
   for(var event:history){var data=map(event.get("data"));String field=number(data.get("locationId"))==id?"location":number(data.get("toLocationId"))==id?"to":"";if(field.isEmpty())continue;var position=SampleLocations.at(data,field);if(mexico&&!"MX".equals(position.site()))continue;var detail=new LinkedHashMap<String,Object>();detail.put("type","event");detail.put("eventId",event.get("id"));detail.put("sampleIdentityId",identity);detail.put("sampleCode",sampleCode);detail.put("name",name);detail.put("locationId",id);detail.put("site",position.site());detail.put("date",text(data.get("date")));detail.put("action",text(event.get("action")));detail.put("qty",number(data.get("qty")));details.add(detail);}
  }
  long events=0;if(!visibleIds.isEmpty()){String in=String.join(",",Collections.nCopies(visibleIds.size(),"?"));var args=new ArrayList<Object>(visibleIds);args.add(id);args.add(id);events=store.jdbc.queryForObject("select count(*) from plm_partner_event where record_id in ("+in+") and "+REFERENCE,Long.class,args.toArray());}var safe=new ArrayList<Map<String,Object>>(sampleRefs.values());safe.addAll(details);return Map.of("id",id,"referenced",!referenced.isEmpty(),"referenceCount",events+visibleIds.size(),"events",events,"records",visibleIds.size(),"batches",batches.size(),"onhand",onhand,"references",safe);
 }
 void resolve(Map<String,Object> command,String field,String site,boolean target){resolve(command,field,site,target,true);}
 void resolve(Map<String,Object> command,String field,String site,boolean target,boolean lock){
  String supplied=text(command.get(SampleLocations.siteField(field)));require(supplied.isEmpty()||site.equals(supplied.toUpperCase(Locale.ROOT)),"不能跨站点移库，请通过原发墨／签收流程办理");String idField=SampleLocations.idField(field);long id=number(command.get(idField));if(id>0){var d=load(id,lock);SampleSiteAccess.write(store,d.get("site"));if(target)require(!Boolean.TRUE.equals(d.get("deleted"))&&"active".equals(d.get("status")),"目标位置不存在或已停用，请重新选择位置");require(site.equals(text(d.get("site"))),"位置不属于所选站点，不能跨站点移库");d.put("locationId",id);SampleLocations.fromPosition(d,command,field);}else {command.put(SampleLocations.siteField(field),site);command.put(field,text(command.get(field)));SampleLocations.normalize(command,field);}
 }
 private String digest(String action,Map<String,Object> input){return PartnerQualityRules.digest(store.json,Map.of("action",action,"input",input));}
 private boolean repeated(long id,String request,String action,String hash){
  var rows=store.jdbc.queryForList("select action,data::text from plm_partner_event where record_id=? and request_id=?",id,request);if(rows.isEmpty())return false;var row=rows.get(0);require(("sample_location_"+action).equals(row.get("action"))&&hash.equals(text(decode(store.json,row.get("data")).get("requestHash"))),"同一提交标识已用于不同位置操作，请核对原结果");return true;
 }
}
